OLD_DEFAULT_BLOCKS = {"scheduled", "webhook", "channel"}


def add_watcher_block(apps, schema_editor):
    MaintenanceWindow = apps.get_model("core", "MaintenanceWindow")
    for window in MaintenanceWindow.objects.all():
        blocks = list(window.blocks or [])
        if set(blocks) == OLD_DEFAULT_BLOCKS and len(blocks) == len(OLD_DEFAULT_BLOCKS):
            window.blocks = blocks + ["watcher"]
            window.save(update_fields=["blocks"])


